package exams

import (
	"encoding/json"
	"os"
	"testing"
)

// Fixture generated by the real frontend buildAssignmentWorkbook helper.
// Checks the browser XLSX writer against the independent native import parser.
func TestUIAssignmentWorkbookRoundTrip(t *testing.T) {
	content, err := os.ReadFile("testdata/assignment-template-ui.xlsx")
	if err != nil {
		t.Fatal(err)
	}
	rows, err := ParseXLSX(content, "assignments.xlsx", "assignments")
	if err != nil || len(rows) != 2 {
		t.Fatalf("parse: %v, rows=%d", err, len(rows))
	}
	e, a, p := auxFixture()
	p.Members[7] = Member{AccountID: 7, Role: "student", Active: true, Login: "0007", DivisionIDs: []int64{2}}
	p.Members[8] = Member{AccountID: 8, Role: "student", Active: true, Login: "=not-a-formula", DivisionIDs: []int64{2}}
	var first map[string]any
	if err = json.Unmarshal(rows[0].Input, &first); err != nil || first["studentLogin"] != "0007" {
		t.Fatalf("leading zeros: %v, %#v", err, first)
	}
	checked, err := ValidateImport(e, a, "assignments", p, rows)
	if err != nil {
		t.Fatal(err)
	}
	for _, row := range checked {
		if len(row.Errors) != 0 {
			t.Fatalf("unexpected validation errors: %#v", row)
		}
	}
	if _, err = CommitImport(e, a, "assignments", p, checked); err != nil {
		t.Fatal(err)
	}
	d := e.Divisions[2]
	if len(d.Assignments) != 2 || len(d.Commissions) != 1 || len(d.Commissions[0].Members) != 1 || d.Commissions[0].Members[0].AccountID != 13 || d.Privileges[7].Limit != 2 || d.Privileges[8].Limit != 2 {
		t.Fatalf("unexpected assignments/one-person commission: %#v", d)
	}
	before, _ := json.Marshal(e)
	if _, err = CommitImport(e, a, "assignments", p, checked); err == nil {
		t.Fatal("duplicate assignments accepted")
	}
	after, _ := json.Marshal(e)
	if string(before) != string(after) {
		t.Fatal("rejected duplicate changed exam")
	}
}
